#define PI 3.14159265359

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float time = (iTime) * 0.54;
    vec3 color = vec3(0.0);
    float intensity = 0.0;

    int NUM_PARTICLES = 60;
    float dynamicScale = 3.14 + sin(iTime * 0.21) * 0.8;

    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (sin(iTime) + 1.0) / 2.0 * id / 30.0;

        float theta = fract(id + particleTime * 0.09) * 20.0 * dynamicScale;
        float phi = fract(id * 1.618 + particleTime * 0.015) * 2.0*dynamicScale;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * -sin(theta),
            cos(phi)
        );

        float angle = time * 0.468;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0,        1.0,  0.0,
            sin(angle), 0.0,  cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 1.4+(sin(time)+1.0)/2.0/2.0);

        float dist = length(uv - screenPos);
        float glow = exp(-dist * 9.0);

        intensity += glow * (0.9 + abs(sin(iTime / 100.0)));
        color += glow * vec3(
            0.4 + 0.6 * sin(id * PI * 2.0),
            0.3 + 0.4 * sin(time * 2.0),
            1.0
        );
    }

 if (intensity < 0.5) {
fragColor = vec4(.40/exp(intensity));
 } else
    if (intensity < 1.9) {
    fragColor = vec4(1.0-color.gbr*vec3(exp(intensity*1.10)),1.0);
    } else {
    fragColor = vec4(color.grb/.5 * intensity, 1.0);
    }
}
